const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const transfer={toefl:'Use the word to explain one cause, comparison, or limitation in a new academic example.',toeic:'Use the expression in a clear request or update. Identify who must do what and by when.',sat:'Use the expression in a short paragraph. Explain how it connects evidence, purpose, or tone.',gre:'Replace the expression with a near-synonym. Explain whether degree, polarity, or contrast changes.',gmat:'Use the expression in a business claim. Name one assumption and one observation that could challenge it.'};
export function renderReasoningMap(lesson,track,key){
 const question=lesson.questions[0];
 return `<section class="card en-reasoning" aria-labelledby="en-reasoning-title"><h2 id="en-reasoning-title">See the learning connections</h2><figure><figcaption>Read from goal to example, then apply the idea in a new situation.</figcaption><ol class="en-reasoning-flow">${[['Goal',lesson.goal],['Observe',lesson.example],['Apply',lesson.task]].map(([label,text])=>`<li><strong>${label}</strong><p>${e(text)}</p></li>`).join('')}</ol></figure><div class="en-reasoning-table" role="region" tabindex="0" aria-label="Vocabulary meaning and use comparison"><table><caption>Compare form, meaning, and use in this lesson</caption><thead><tr><th scope="col">Expression</th><th scope="col">Meaning</th><th scope="col">Example</th></tr></thead><tbody>${lesson.words.slice(0,3).map(word=>`<tr>${word.map(value=>`<td>${e(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><details><summary>Explain a choice before checking the answer</summary><p>${e(question[0])}</p><ul>${question[1].map(option=>`<li>${e(option)}</li>`).join('')}</ul><details><summary>Compare your reason with the explanation</summary><p><strong>${e(question[2])}</strong></p><p>${e(question[3])}</p></details></details><h3>Transfer the idea</h3><p>Start with “${e(lesson.words[0][0])}”. ${e(transfer[track.id])}</p><p>Write your new example and explain one decision in the reflection below. Reading the model does not count as independent recall.</p><a class="button" href="#lesson/${e(key)}/quiz">Try the practice check without notes</a></section>`;
}
